if (!token) throw new Error('N8N_CONEXAO_SERES_JORNADA_WEBHOOK_TOKEN não configurado.');
const authorization = String(h.authorization || h.Authorization || '').trim();
if (authorization !== `Bearer ${token}`) throw new Error('Unauthorized');
const eventType = String(b.eventType || '').trim();
if (!['jornada_yoga_registration_created','jornada_yoga_payment_paid'].includes(eventType)) {
  throw new Error('Evento inválido para a Jornada Yoga.');
}
if (String(b.eventId || '') !== 'jornada-yoga-2026') throw new Error('eventId inválido.');
const paymentId = String(b.paymentId || '').trim();
const customerName = String(b.customerName || '').trim();
const customerEmail = String(b.customerEmail || '').trim().toLowerCase();
const customerWhatsapp = String(b.customerWhatsapp || '').replace(/\D/g,'');
if (!paymentId || !customerName || !customerEmail) throw new Error('Dados obrigatórios ausentes.');
if (eventType === 'jornada_yoga_registration_created' && !String(b.invoiceUrl || '').trim()) {
  throw new Error('Link de pagamento ausente no cadastro da Jornada.');
}
return [{
  json:{
    ...b,
    eventType,
    paymentId,
    customerName,
    customerEmail,
    customerWhatsapp,
    messageApprovalStatus:'APPROVED'
  }
}];

